-- IPA SG official past questions: 2019 autumn morning, questions 31-50.
-- Question text/options cross-checked against item-level question pages; answer keys cross-checked against IPA official answer PDF.
-- For Q44 the original arrow diagram is a visual asset in the official PDF; the item is kept with an explicit source note.
INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2019f-am-31','exam-sg','刑法','standard','single_choice','【2019年度 令和元年秋期 午前 問31】企業において業務で使用されているコンピュータに，記憶媒体を介してマルウェアを侵入させ，そのコンピュータのデータを消去した者がいたとき，その者を処罰の対象とする法律はどれか。','[{"id":"a","text":"刑法"},{"id":"b","text":"製造物責任法"},{"id":"c","text":"不正アクセス禁止法"},{"id":"d","text":"プロバイダ責任制限法"}]','"a"','マルウェアを侵入させデータを消去する行為は，刑法上の電磁的記録毀損などに該当し得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-32','exam-sg','法務・技術者倫理','standard','single_choice','【2019年度 令和元年秋期 午前 問32】技術者の活動に関係する法律のうち，罰則規定のないものはどれか。','[{"id":"a","text":"公益通報者保護法"},{"id":"b","text":"個人情報保護法"},{"id":"c","text":"特許法"},{"id":"d","text":"不正競争防止法"}]','"a"','2019年試験当時の公益通報者保護法には罰則規定がなかった。現在の法改正状況とは区別する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-33','exam-sg','契約','standard','single_choice','【2019年度 令和元年秋期 午前 問33】シュリンクラップ契約において，ソフトウェアの使用許諾契約が成立するのはどの時点か。','[{"id":"a","text":"購入したソフトウェアの代金を支払った時点"},{"id":"b","text":"ソフトウェアの入ったDVD-ROMを受け取った時点"},{"id":"c","text":"ソフトウェアの入ったDVD-ROMの包装を解いた時点"},{"id":"d","text":"ソフトウェアをPCにインストールした時点"}]','"c"','シュリンクラップ契約は，包装を開封する行為によって使用許諾に同意したとみなす契約形態である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-34','exam-sg','知的財産権','standard','single_choice','【2019年度 令和元年秋期 午前 問34】A社は，B社と著作物の権利に関する特段の取決めをせず，A社の要求仕様に基づいて，販売管理システムのプログラム作成をB社に委託した。プログラムの著作権は原則として誰に帰属するか。','[{"id":"a","text":"A社とB社が協議して決定する"},{"id":"b","text":"A社とB社の共有となる"},{"id":"c","text":"A社に帰属する"},{"id":"d","text":"B社に帰属する"}]','"d"','著作権の特段の合意がない場合，作成したプログラムの著作権は原則として作成者であるB社に帰属する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-35','exam-sg','労働者派遣法','standard','single_choice','【2019年度 令和元年秋期 午前 問35】A社は，A社で使うソフトウェアの開発作業をB社に実施させる契約を，B社と締結した。締結した契約が労働者派遣であるものはどれか。','[{"id":"a","text":"A社の責任者がB社の従業員に作業の進め方を指示する"},{"id":"b","text":"B社の責任者がB社の従業員に指示し，A社は成果物を検収する"},{"id":"c","text":"B社の従業員がB社の指示に従い，B社所有の機器を使って作業する"},{"id":"d","text":"B社の責任者がB社の従業員に指示し，A社の事業所内で作業する"}]','"a"','派遣か請負かは契約名ではなく指揮命令関係で判断する。派遣先であるA社が直接指示する場合は労働者派遣に当たる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-36','exam-sg','労働基準法','standard','single_choice','【2019年度 令和元年秋期 午前 問36】常時10名以上の従業員を有するソフトウェア開発会社が，社内の情報セキュリティ管理を強化するために，秘密情報を扱う担当従業員の扱いを見直すこととした。労働法に照らし，適切な行為はどれか。','[{"id":"a","text":"就業規則に秘密漏えい禁止の一般的な規定があるときに，担当従業員の職務に即して秘密の内容を特定する個別合意を行う"},{"id":"b","text":"従業員の意見を聴かずに漏えい禁止と処分の規定を就業規則に追加する"},{"id":"c","text":"就業規則よりも処分を重くした個別合意を行う"},{"id":"d","text":"秘密に関する規定は就業規則に設けず，各従業員と個別合意だけを行う"}]','"a"','秘密の内容を職務に即して明確にする個別合意は適切。就業規則の作成・変更には所定の手続が必要である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-37','exam-sg','内部統制','standard','single_choice','【2019年度 令和元年秋期 午前 問37】入出金管理システムから出力された入金データファイルを，売掛金管理システムが読み込んでマスタファイルを更新する。システム間で受け渡されたデータの正確性及び網羅性を確保するコントロールはどれか。','[{"id":"a","text":"売掛金管理システムにおける入力データと出力結果とのランツーランコントロール"},{"id":"b","text":"売掛金管理システムのマスタファイル更新におけるタイムスタンプ機能"},{"id":"c","text":"入金額及び入金データ件数のコントロールトータルのチェック"},{"id":"d","text":"入出金管理システムへの入力のエディットバリデーションチェック"}]','"c"','受渡し元と受渡し先で合計金額と件数を照合するコントロールトータルは，欠落や誤りの検出に役立つ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-38','exam-sg','内部統制','standard','single_choice','【2019年度 令和元年秋期 午前 問38】内部統制の基本的要素を，統制環境，リスクの評価と対応，統制活動，情報と伝達，モニタリング，ITへの対応に分類したとき，統制活動に該当するものはどれか。','[{"id":"a","text":"経営者が経営方針を全社的に明示する"},{"id":"b","text":"情報システムの故障に備えて保険契約に加入する"},{"id":"c","text":"内部監査部門が定期的に業務監査を実施する"},{"id":"d","text":"発注業務と検収業務をそれぞれ別の者に担当させる"}]','"d"','職務分掌は統制活動の代表例。方針の明示は統制環境，保険はリスク対応，内部監査はモニタリングに当たる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-39','exam-sg','システム監査','standard','single_choice','【2019年度 令和元年秋期 午前 問39】データの生成から入力，処理，出力，活用までのプロセス及び組み込まれているコントロールを，システム監査人が書面上又は実際に追跡する技法はどれか。','[{"id":"a","text":"インタビュー法"},{"id":"b","text":"ウォークスルー法"},{"id":"c","text":"監査モジュール法"},{"id":"d","text":"ペネトレーションテスト法"}]','"b"','ウォークスルー法はデータ処理の流れと統制を順に追跡して確認する技法である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-40','exam-sg','システム監査','standard','single_choice','【2019年度 令和元年秋期 午前 問40】アクセス制御を監査するシステム監査人の行為のうち，適切なものはどれか。','[{"id":"a","text":"ソフトウェアのアクセス制御管理台帳を作成し保管する"},{"id":"b","text":"データのアクセス制御管理規程を閲覧する"},{"id":"c","text":"ネットワークのアクセス制御管理方針を制定する"},{"id":"d","text":"ハードウェアのアクセス制御運用手続を実施する"}]','"b"','監査人は規程などを閲覧して証拠を収集する。管理台帳の作成や方針制定，運用実施は管理側の業務である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-41','exam-sg','インシデント管理','standard','single_choice','【2019年度 令和元年秋期 午前 問41】ITサービスマネジメントにおいて，サービスの計画外の中断，品質低下，又は顧客へのサービスにまだ影響していない事象を何というか。','[{"id":"a","text":"インシデント"},{"id":"b","text":"既知の誤り"},{"id":"c","text":"変更要求"},{"id":"d","text":"問題"}]','"a"','インシデントはサービスの中断や品質低下，またはサービスに影響し得る事象を扱う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-42','exam-sg','サービス運用','standard','single_choice','【2019年度 令和元年秋期 午前 問42】ヒューマンエラーに起因する障害を発生しにくくするエラープルーフ化の例として，運用作業で最も適切なものはどれか。','[{"id":"a","text":"複数のウィンドウを間違えないよう，ウィンドウごとに背景色を変える"},{"id":"b","text":"長時間の監視作業で2時間おきに交代して休憩する"},{"id":"c","text":"過去のヒヤリハット情報を共有する"},{"id":"d","text":"臨時作業の教育や訓練を定期的に行う"}]','"a"','画面の背景色を変える工夫は，人の注意力だけに頼らず誤操作を起こしにくくする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-43','exam-sg','プロジェクトマネジメント','standard','single_choice','【2019年度 令和元年秋期 午前 問43】プロジェクトライフサイクルの一般的な特性はどれか。','[{"id":"a","text":"要員数は開始時が最多で，進行とともに減少し，完了直前に再び増加する"},{"id":"b","text":"ステークホルダがコストを変えずに成果物へ及ぼせる影響は完了直前が最大である"},{"id":"c","text":"完了に近づくほど変更やエラー修正の影響は小さくなる"},{"id":"d","text":"リスクはプロジェクト完了に近づくにつれて減少する"}]','"d"','一般にプロジェクトの不確実性とリスクは，進行して完了に近づくにつれて減少する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-44','exam-sg','プロジェクトの時間','standard','single_choice','【2019年度 令和元年秋期 午前 問44】あるプロジェクトの日程計画をアローダイアグラムで示す。クリティカルパスはどれか。','[{"id":"a","text":"A，C，E，F"},{"id":"b","text":"A，D，G"},{"id":"c","text":"B，E，F"},{"id":"d","text":"B，E，G"}]','"c"','クリティカルパスは所要日数の合計が最も長い経路であり，この問題ではB→E→Fである。図はIPA公開問題の図を参照すること。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-45','exam-sg','システム性能','standard','single_choice','【2019年度 令和元年秋期 午前 問45】Webシステムの性能指標のうち，応答時間の説明はどれか。','[{"id":"a","text":"ブラウザ上の問合せボタンが押されてから，結果を表示し始めるまでの時間"},{"id":"b","text":"ブラウザ起動から最初のWebページの全データ表示が完了するまでの時間"},{"id":"c","text":"サーバ側のトランザクション処理完了から，ブラウザが結果を表示し始めるまでの時間"},{"id":"d","text":"ダウンロード要求からダウンロード完了までの時間"}]','"a"','応答時間は利用者の操作から結果が返り始めるまでの待ち時間である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-46','exam-sg','トランザクション処理','standard','single_choice','【2019年度 令和元年秋期 午前 問46】データベースのトランザクションに関する記述のうち，適切なものはどれか。','[{"id":"a","text":"他のトランザクションに更新されないようにするため，アプリケーションがテーブルのロックを解放した"},{"id":"b","text":"障害で異常終了したトランザクションをDBMSがロールフォワードした"},{"id":"c","text":"更新結果を確定するために，アプリケーションがトランザクションをロールバックした"},{"id":"d","text":"複数のトランザクション間でデッドロックが発生したので，DBMSがトランザクションをロールバックした"}]','"d"','デッドロックの解消では，DBMSが一方のトランザクションをロールバックすることがある。確定はコミットで行う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-47','exam-sg','インターネット技術','standard','single_choice','【2019年度 令和元年秋期 午前 問47】PCがWebサーバ，メールサーバ，他のPCなどと通信を始める際に，通信相手のIPアドレスを問い合わせる仕組みはどれか。','[{"id":"a","text":"ARP"},{"id":"b","text":"DHCP"},{"id":"c","text":"DNS"},{"id":"d","text":"NAT"}]','"c"','DNSはドメイン名をIPアドレスに対応付ける名前解決の仕組みである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-48','exam-sg','業務プロセス','standard','single_choice','【2019年度 令和元年秋期 午前 問48】RPAを活用することによって業務の改善を図ったものはどれか。','[{"id":"a","text":"画像解析で規格外の果物を選別する装置を導入した"},{"id":"b","text":"定型的かつ大量のコピー＆ペースト作業をソフトウェアで自動化した"},{"id":"c","text":"倉庫作業者にパワーアシストスーツを着用させた"},{"id":"d","text":"ビッグデータでタクシー需要が多い地域を予測した"}]','"b"','RPAはソフトウェアロボットによって定型的な事務作業を自動化する技術である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-49','exam-sg','調達・RFP','standard','single_choice','【2019年度 令和元年秋期 午前 問49】情報システムを取得するための提案依頼書（RFP）の作成と提案依頼に当たり，ユーザ企業側の対応として適切なものはどれか。','[{"id":"a","text":"作成の手間を省くため要求事項を最小限にし，曖昧な点はベンダに確認させる"},{"id":"b","text":"実現性の事前確認をせず，調査や検討をすべてベンダに任せる"},{"id":"c","text":"要求事項の重要度をRFP作成時点で設定する"},{"id":"d","text":"機能ではなく具体的な製品名や実現手段を細かく指定する"}]','"c"','要求事項の重要度を明示すると，ベンダは優先順位を踏まえた現実的な提案を作りやすい。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-50','exam-sg','データ利活用','standard','single_choice','【2019年度 令和元年秋期 午前 問50】アンケートの自由記述欄に記入された文章における単語の出現頻度などを分析する手法はどれか。','[{"id":"a","text":"アクセスログ分析"},{"id":"b","text":"シックスシグマ"},{"id":"c","text":"テキストマイニング"},{"id":"d","text":"マーケットバスケット分析"}]','"c"','テキストマイニングは文章データから単語の出現頻度や関連などを分析する手法である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja');
